begin;

create policy property_amenities_org on public.property_amenities for all to authenticated using(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id)));
create policy property_photos_org on public.property_photos for all to authenticated using(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id)));
create policy property_rules_org on public.property_rules for all to authenticated using(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id)));
create policy property_integrations_org on public.property_integrations for all to authenticated using(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id)));
create policy calendar_sources_org on public.calendar_sources for all to authenticated using(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id,array['host_owner','host_manager']::public.app_role[]))) with check(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id,array['host_owner','host_manager']::public.app_role[])));
create policy sync_runs_org on public.reservation_sync_runs for all to authenticated using(exists(select 1 from public.calendar_sources c join public.properties p on p.id=c.property_id where c.id=calendar_source_id and public.is_org_member(p.organization_id,array['host_owner','host_manager']::public.app_role[]))) with check(exists(select 1 from public.calendar_sources c join public.properties p on p.id=c.property_id where c.id=calendar_source_id and public.is_org_member(p.organization_id,array['host_owner','host_manager']::public.app_role[])));
create policy guest_preferences_org on public.guest_preferences for all to authenticated using(exists(select 1 from public.guests g where g.id=guest_id and (g.profile_id=auth.uid() or public.is_org_member(g.organization_id)))) with check(exists(select 1 from public.guests g where g.id=guest_id and (g.profile_id=auth.uid() or public.is_org_member(g.organization_id))));
create policy guest_consents_org on public.guest_consents for all to authenticated using(exists(select 1 from public.guests g where g.id=guest_id and (g.profile_id=auth.uid() or public.is_org_member(g.organization_id)))) with check(exists(select 1 from public.guests g where g.id=guest_id and (g.profile_id=auth.uid() or public.is_org_member(g.organization_id))));
create policy guest_tokens_host on public.guest_portal_tokens for all to authenticated using(exists(select 1 from public.reservations r where r.id=reservation_id and public.is_org_member(r.organization_id,array['host_owner','host_manager','property_staff']::public.app_role[]))) with check(exists(select 1 from public.reservations r where r.id=reservation_id and public.is_org_member(r.organization_id,array['host_owner','host_manager','property_staff']::public.app_role[])));
create policy guest_messages_org on public.guest_messages for all to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy trip_days_access on public.trip_days for all to authenticated using(exists(select 1 from public.trip_plans t where t.id=trip_plan_id and (t.owner_user_id=auth.uid() or public.is_org_member(t.organization_id)))) with check(exists(select 1 from public.trip_plans t where t.id=trip_plan_id and (t.owner_user_id=auth.uid() or public.is_org_member(t.organization_id))));
create policy trip_items_access on public.trip_items for all to authenticated using(exists(select 1 from public.trip_days d join public.trip_plans t on t.id=d.trip_plan_id where d.id=trip_day_id and (t.owner_user_id=auth.uid() or public.is_org_member(t.organization_id)))) with check(exists(select 1 from public.trip_days d join public.trip_plans t on t.id=d.trip_plan_id where d.id=trip_day_id and (t.owner_user_id=auth.uid() or public.is_org_member(t.organization_id))));
create policy trip_collaborators_access on public.trip_collaborators for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.trip_plans t where t.id=trip_plan_id and t.owner_user_id=auth.uid()));
create policy recommendations_host_manage on public.host_recommendations for all to authenticated using(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id,array['host_owner','host_manager']::public.app_role[]))) with check(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id,array['host_owner','host_manager']::public.app_role[])));
create policy upgrades_host_manage on public.upgrades for all to authenticated using(public.is_org_member(organization_id,array['host_owner','host_manager']::public.app_role[])) with check(public.is_org_member(organization_id,array['host_owner','host_manager']::public.app_role[]));
create policy upgrade_availability_host on public.upgrade_availability for all to authenticated using(exists(select 1 from public.upgrades u where u.id=upgrade_id and public.is_org_member(u.organization_id,array['host_owner','host_manager']::public.app_role[]))) with check(exists(select 1 from public.upgrades u where u.id=upgrade_id and public.is_org_member(u.organization_id,array['host_owner','host_manager']::public.app_role[])));
create policy upgrade_orders_host_read on public.upgrade_orders for select to authenticated using(public.is_org_member(organization_id));
create policy upgrade_items_host_read on public.upgrade_order_items for select to authenticated using(exists(select 1 from public.upgrade_orders o where o.id=order_id and public.is_org_member(o.organization_id)));
create policy vendors_owner on public.vendors for select to authenticated using(owner_user_id=auth.uid() or public.is_org_member(organization_id));
create policy vendor_apply on public.vendors for insert to authenticated with check(owner_user_id=auth.uid());
create policy vendor_services_owner on public.vendor_services for all to authenticated using(exists(select 1 from public.vendors v where v.id=vendor_id and v.owner_user_id=auth.uid())) with check(exists(select 1 from public.vendors v where v.id=vendor_id and v.owner_user_id=auth.uid()));
create policy cleaning_checklists_access on public.cleaning_checklists for all to authenticated using(exists(select 1 from public.cleaning_assignments a where a.id=cleaning_assignment_id and public.is_org_member(a.organization_id))) with check(exists(select 1 from public.cleaning_assignments a where a.id=cleaning_assignment_id and public.is_org_member(a.organization_id)));
create policy cleaning_photos_access on public.cleaning_photos for all to authenticated using(exists(select 1 from public.cleaning_assignments a where a.id=cleaning_assignment_id and public.is_org_member(a.organization_id))) with check(created_by=auth.uid() and exists(select 1 from public.cleaning_assignments a where a.id=cleaning_assignment_id and public.is_org_member(a.organization_id)));
create policy maintenance_quotes_org on public.maintenance_quotes for all to authenticated using(exists(select 1 from public.maintenance_tickets t where t.id=maintenance_ticket_id and public.is_org_member(t.organization_id))) with check(exists(select 1 from public.maintenance_tickets t where t.id=maintenance_ticket_id and public.is_org_member(t.organization_id)));
create policy inventory_org on public.inventory_items for all to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy inventory_counts_org on public.inventory_counts for all to authenticated using(exists(select 1 from public.inventory_items i where i.id=inventory_item_id and public.is_org_member(i.organization_id))) with check(counted_by=auth.uid() and exists(select 1 from public.inventory_items i where i.id=inventory_item_id and public.is_org_member(i.organization_id)));
create policy restock_org on public.restock_tasks for all to authenticated using(exists(select 1 from public.inventory_items i where i.id=inventory_item_id and public.is_org_member(i.organization_id))) with check(exists(select 1 from public.inventory_items i where i.id=inventory_item_id and public.is_org_member(i.organization_id)));
create policy notifications_insert_self on public.notifications for insert to authenticated with check(user_id=auth.uid() and (organization_id is null or public.is_org_member(organization_id)));
create policy subscriptions_org_read on public.subscriptions for select to authenticated using(public.is_org_member(organization_id));
create policy entitlements_org_read on public.entitlements for select to authenticated using(public.is_org_member(organization_id));
create policy payments_org_read on public.payments for select to authenticated using(public.is_org_member(organization_id));
create policy audit_reports_org on public.audit_reports for all to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy audit_findings_org on public.audit_findings for select to authenticated using(exists(select 1 from public.audit_reports r where r.id=audit_report_id and public.is_org_member(r.organization_id)));
create policy review_imports_org on public.review_imports for all to authenticated using(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id))) with check(imported_by=auth.uid() and exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id)));
create policy review_insights_org on public.review_insights for select to authenticated using(exists(select 1 from public.properties p where p.id=property_id and public.is_org_member(p.organization_id)));
create policy ai_runs_org_read on public.ai_runs for select to authenticated using(user_id=auth.uid() or public.is_org_member(organization_id));
create policy integration_logs_org_read on public.integration_logs for select to authenticated using(public.is_org_member(organization_id));
create policy audit_logs_org_read on public.audit_logs for select to authenticated using(public.is_org_member(organization_id,array['host_owner','host_manager']::public.app_role[]));
create policy support_cases_owner on public.support_cases for select to authenticated using(opened_by=auth.uid() or public.is_org_member(organization_id));
create policy support_cases_create on public.support_cases for insert to authenticated with check(opened_by=auth.uid() and (organization_id is null or public.is_org_member(organization_id)));

commit;
